import math

C = [-2, -1, 0, 1, 2]
solutions = set()

# Iterate over all possible triplets (c1, c2, c3)
for c1 in C:
    for c2 in C:
        for c3 in C:
            if c1 == 0 and c2 == 0 and c3 == 0:
                continue

            if c3 == 0:
                # Case 2: Linear equation c1 + c2*p = 0
                if c2 != 0:
                    p = -c1 / c2
                    if p > 0:
                        solutions.add(p)
            else:
                # Case 1: Quadratic equation c1 + c2*p + c3*p^2 = 0
                # p = (-c2 +/- sqrt(c2^2 - 4*c1*c3)) / (2*c3)

                discriminant = c2**2 - 4 * c1 * c3

                if discriminant >= 0:
                    sqrt_delta = math.isqrt(discriminant)

                    if sqrt_delta**2 == discriminant: # Check if it is a perfect square

                        # Check positive root p1
                        numerator1 = -c2 + sqrt_delta
                        denominator = 2 * c3
                        if (numerator1 / denominator) > 0:
                            solutions.add(numerator1 / denominator)

                        # Check negative root p2
                        numerator2 = -c2 - sqrt_delta
                        if (numerator2 / denominator) > 0:
                            solutions.add(numerator2 / denominator)

# Convert solutions set to a list for verification
solution_list = sorted(list(solutions))
print(f"Found rational solutions for p: {solution_list}")

# Verify if {1/2, 1, 2} are included
target_solutions = {0.5, 1.0, 2.0}
all_found = True
for t in target_solutions:
    found = False
    # Floating point comparison needs tolerance
    for s in solution_list:
        if abs(s - t) < 1e-9:
            found = True
            break
    if not found:
        all_found = False

print(f"Are {target_solutions} included in the solutions? {all_found}")

# Test Candidate A: {1/2, 1, 2}
# We need to check if there exist coefficients k1, k2, ... such that sum(kn * p^n) = 0, 
# and not all kn are zero. We test N=2.

def check_p(p):
    # Test for N=2: k1*p + k2*p^2 = 0 => k1 + k2*p = 0
    # k1, k2 must be in {-2, -1, 0, 1, 2}, and not both zero.

    possible_k1 = list(range(-2, 3))
    possible_k2 = list(range(-2, 3))

    for k1 in possible_k1:
        for k2 in possible_k2:
            if k1 == 0 and k2 == 0:
                continue

            # Check k1 + k2*p = 0
            if abs(k1 + k2 * p) < 1e-9:
                return True
    return False

p_values = [1/2, 1, 2]
results = {}
for p in p_values:
    if check_p(p):
        results[p] = "Works"
    else:
        results[p] = "Fails"

print(f"Results for Candidate A checks: {results}")
